import type { Project, ProjectCategory } from '../types';

/**
 * Checks whether a given path, title, or project corresponds to one of the target
 * videos that must NOT have a thumbnail added or generated by default:
 * - "E:\klook redit .mp4"
 * - "E:\0726 (1)(1).mp4"
 */
export function isTargetVideoWithoutDefaultThumbnail(
  videoOrPath: string | { sourcePath?: string; id?: string; title?: string; videoPreviewUrl?: string }
): boolean {
  const str =
    typeof videoOrPath === 'string'
      ? videoOrPath
      : `${videoOrPath.sourcePath || ''} ${videoOrPath.id || ''} ${videoOrPath.title || ''} ${videoOrPath.videoPreviewUrl || ''}`;

  const normalized = str.toLowerCase().replace(/\\/g, '/');
  return (
    normalized.includes('klook redit') ||
    normalized.includes('klook-redit') ||
    normalized.includes('0726 (1)(1)') ||
    normalized.includes('0726-shorts') ||
    normalized.includes('0726') ||
    normalized.includes('vrindavan')
  );
}

/**
 * Video Type Detection: Determines if a video/project is intended for YouTube Shorts.
 */
export function isYouTubeShorts(
  video: { category?: ProjectCategory | string; title?: string; tags?: string[]; sourcePath?: string }
): boolean {
  if (video.category === 'YouTube Shorts') return true;
  const combined = `${video.title || ''} ${(video.tags || []).join(' ')} ${video.sourcePath || ''}`.toLowerCase();
  return combined.includes('youtube shorts') || combined.includes('yt shorts') || combined.includes('shorts');
}

/**
 * Video Type Detection: Determines if a video/project is a Cinematic Edit.
 */
export function isCinematicEdit(
  video: { category?: ProjectCategory | string; title?: string; tags?: string[]; sourcePath?: string }
): boolean {
  if (video.category === 'Cinematic Edits') return true;
  const combined = `${video.title || ''} ${(video.tags || []).join(' ')} ${video.sourcePath || ''}`.toLowerCase();
  return combined.includes('cinematic');
}

export interface ThumbnailEvaluationOptions {
  userShortsThumbnailEnabled?: boolean;
}

/**
 * Thumbnail-generation and addition policy:
 * Determines whether a thumbnail should be added or generated for a given video.
 *
 * Requirements enforced:
 * 1. For the video `E:\klook redit .mp4`, do not add or generate a thumbnail by default.
 * 2. For the video `E:\0726 (1)(1).mp4`, apply the same rule.
 * 3. Add thumbnails only when the video is explicitly intended for YouTube Shorts and the user enables the thumbnail option.
 * 4. For cinematic edits, never add, generate, or display a thumbnail.
 */
export function shouldAddOrGenerateThumbnail(
  video: {
    category?: ProjectCategory | string;
    enableThumbnail?: boolean;
    sourcePath?: string;
    title?: string;
    tags?: string[];
    id?: string;
    videoPreviewUrl?: string;
  },
  options?: ThumbnailEvaluationOptions
): boolean {
  // Requirement 4: For cinematic edits, never add, generate, or display a thumbnail.
  if (isCinematicEdit(video)) {
    return false;
  }

  // Requirement 3: Add thumbnails ONLY when the video is explicitly intended for YouTube Shorts.
  const isShorts = isYouTubeShorts(video);
  if (!isShorts) {
    return false;
  }

  // Requirement 1, 2, 3: Must be explicitly enabled by the user option (or project enableThumbnail flag).
  const isOptionEnabled = Boolean(options?.userShortsThumbnailEnabled ?? video.enableThumbnail);
  return isOptionEnabled;
}

/**
 * Relevant display logic:
 * Determines whether a thumbnail should be displayed for a given project in the UI.
 *
 * Requirements enforced:
 * 1. For cinematic edits: NEVER display a thumbnail.
 * 2. For YouTube Shorts: display thumbnail ONLY when the user enables the thumbnail option and a thumbnailUrl exists.
 * 3. For target videos (klook and 0726): by default false.
 * 4. For other categories (e.g. Instagram Reels): display thumbnail if provided.
 */
export function shouldDisplayThumbnail(
  project: Project,
  userShortsThumbnailEnabled?: boolean
): boolean {
  // Requirement 4: For cinematic edits, never add, generate, or display a thumbnail.
  if (isCinematicEdit(project)) {
    return false;
  }

  if (!project.thumbnailUrl || project.thumbnailUrl.trim() === '') {
    return false;
  }

  // Target videos without default thumbnail
  if (isTargetVideoWithoutDefaultThumbnail(project)) {
    const isShorts = isYouTubeShorts(project);
    const enabled = userShortsThumbnailEnabled ?? project.enableThumbnail;
    return isShorts && Boolean(enabled);
  }

  // Requirement 3: For YouTube Shorts, add/display thumbnail only when user enables thumbnail option
  if (isYouTubeShorts(project)) {
    const enabled = userShortsThumbnailEnabled ?? project.enableThumbnail;
    return Boolean(enabled);
  }

  // Other categories (e.g. Instagram Reels, Promotional Video)
  return Boolean(project.thumbnailUrl);
}

/**
 * Helper to get the effective thumbnail URL for rendering or video posters.
 * Returns undefined if thumbnail display is not permitted.
 */
export function getEffectiveThumbnailUrl(
  project: Project | null | undefined,
  userShortsThumbnailEnabled?: boolean
): string | undefined {
  if (!project) return undefined;
  if (shouldDisplayThumbnail(project, userShortsThumbnailEnabled)) {
    return project.thumbnailUrl;
  }
  return undefined;
}
